css:
.heading-block{
    width: 50%;
    float: left;
    height: 100px;
}
.print-heading {
    border-bottom: 0 !important
}
.lbl_title{
    color: #076EBB;
    border-bottom: 1px solid;

}
.info-block{
    width:100px;
    float: right;
}
.print-format th{
    background-color: #ffffff !important;
    color: black;
}
th.table-sr{
 text-indent: -9999px;
  line-height: 0; /* Collapse the original line */
}
th.table-sr:after{
   content: "No";
  text-indent: 0;
  display: block;
  line-height: initial; /* New content takes up original line height */
}
.header-logo {
  /* before line */
  border-right: 3px solid #6e6e6e;
}
.headervl {
  display: inline;
  padding: 0.1em;
  font-size: 24px;
  color:#E19E1E;
  font-weight: bold;
  width: 100%;
}
.headervl > .header-title {
    margin-left: 25rem;
}

.headervl .header-title .header-subtitle {
    font-size: 14px;
    margin-left: 0.8em;
    display:block;
}

.termsname {
  background-color: #6D6D6D;
  color: white;
  text-weight: bold;
  font-size: 110%;
}

.footer-notes {
    padding-bottom: 3em;
    padding-top: 0.7em;
}

.footerinfo {
        background: #6D6D6D;
        color: white;
        font-size: 10px;
}

.div-striped > div:nth-child(odd) {
  background-color: #ebebeb;
}

table {
    border:none;
}
table tr td, table tr th {
    border: 1.7px solid #6e6e6e !important;
}

.total-row {
    border: none !important;
}
.total-row th {
    text-align: right !important;
    border: none !important;
}

.total-row td {
    font-weight: bold;
    border: 1.7px solid #6e6e6e;
}

.value-bolded {
    font-weight: bold;
    float: right;
}

.value-bolded > vb-value {
    text-transform: uppercase;
}


#footer-html2 {
    display: none;
}

@media print {
 #footer-html2 {
    display: block;
    position: fixed;
    bottom: 0;
    left: 0;
    width: 100%;
 }
}
